const designAnalysis = $('Agent 1: Design Critic').item.json.output;
const copyAnalysis = $('Agent 2: Copywriter').item.json.output;
const seoAnalysis = $('Agent 3: SEO Specialist').item.json.output;
const strategyAnalysis = $('Agent 4: Growth Strategist').item.json.output;

const userData = $('Initialize Variables').item.json;
const pageData = $('Extract Page Elements').item.json;

const gradeMatch = strategyAnalysis.match(/Grade:\s*([A-F][+-]?)/i);
const grade = gradeMatch ? gradeMatch[1] : 'N/A';

const scoreMatch = strategyAnalysis.match(/Score:\s*(\d+)\/100/i);
const score = scoreMatch ? scoreMatch[1] : '0';

const getGradeColor = (g) => {
  if (g.startsWith('A')) return '#10b981';
  if (g.startsWith('B')) return '#3b82f6';
  if (g.startsWith('C')) return '#f59e0b';
  if (g.startsWith('D')) return '#f97316';
  return '#ef4444';
};

const gradeColor = getGradeColor(grade);

const formatSection = (content, title, icon, color) => `
<div style="margin: 30px 0; padding: 20px; background: #f8f9fa; border-left: 4px solid ${color}; border-radius: 4px;">
  <h2 style="margin: 0 0 15px 0; color: ${color}; font-size: 20px;">${icon} ${title}</h2>
  <div style="white-space: pre-line; line-height: 1.8; color: #333;">${content}</div>
</div>`;

const emailHtml = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
</head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.6; color: #333; background: #f5f5f5; margin: 0; padding: 0;">
<div style="max-width: 800px; margin: 0 auto; background: white;">
  <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 40px 30px; text-align: center;">
    <h1 style="margin: 0; font-size: 32px;">🎯 Your Landing Page Audit</h1>
    <p style="margin: 10px 0 0 0;">Professional analysis from 4 AI specialists</p>
  </div>

  <div style="background: white; text-align: center; padding: 40px 20px; border-bottom: 2px solid #e9ecef;">
    <div style="width: 160px; height: 160px; border-radius: 50%; border: 8px solid ${gradeColor}; display: inline-flex; flex-direction: column; align-items: center; justify-content: center; margin-bottom: 20px;">
      <div style="font-size: 64px; font-weight: 700; color: ${gradeColor}; line-height: 1;">${grade}</div>
      <div style="font-size: 18px; color: #6c757d;">${score}/100</div>
    </div>
    <h2 style="margin: 0; color: #2c3e50;">${pageData.page_title}</h2>
    <p style="color: #6c757d; margin: 10px 0 0 0;">${userData.landing_page_url}</p>
  </div>

  <div style="padding: 30px;">
    ${formatSection(strategyAnalysis, 'Strategic Overview', '🚀', '#667eea')}
    ${formatSection(designAnalysis, 'Design & UX Analysis', '🎨', '#e74c3c')}
    ${formatSection(copyAnalysis, 'Copywriting Analysis', '✍️', '#3498db')}
    ${formatSection(seoAnalysis, 'SEO & Technical Analysis', '🔍', '#2ecc71')}

    <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 40px; text-align: center; margin: 40px 0; border-radius: 8px;">
      <h2 style="margin: 0 0 15px 0; font-size: 28px;">Want Us To Fix Everything?</h2>
      <p style="margin: 0 0 25px 0; font-size: 18px;">Our experts can implement all recommendations and boost your conversions.</p>
      <a href="mailto:mark.marin@evervise.com?subject=Landing Page Optimization Quote" style="display: inline-block; background: white; color: #667eea; padding: 15px 40px; text-decoration: none; border-radius: 6px; font-weight: 700; font-size: 18px;">Get a Custom Quote →</a>
    </div>
  </div>

  <div style="background: #2c3e50; color: white; padding: 30px; text-align: center;">
    <h3 style="margin: 0 0 15px 0;">Evervise - Digital Marketing & Automation</h3>
    <p style="margin: 10px 0;"><a href="https://evervise.ai" style="color: #3498db; text-decoration: none;">evervise.ai</a></p>
  </div>
</div>
</body>
</html>`;

return {
  email_html: emailHtml,
  email_subject: `🎯 Your Landing Page Grade: ${grade} (${score}/100) - ${pageData.page_title}`,
  user_email: userData.user_email,
  grade,
  score,
  url: userData.landing_page_url
};
